/**
 * @summary Replay parse queue status, parsed totals, oldest queued items
 */
export const GetAdminParseQueueStatsResponse = zod.record(
  zod.string(),
  zod.unknown(),
);

/**
 * @summary OpenDota API key usage (in-memory counters, resets on restart)
 */
export const GetAdminOdUsageResponse = zod.object({
  today: zod.number(),
  last7d: zod.number(),
  last30d: zod.number(),
  estimatedCostUsdToday: zod.number(),
  estimatedCostUsdLast30d: zod.number(),
  hasKey: zod.boolean(),
  history: zod.array(
    zod.object({
      date: zod.string(),
      count: zod.number(),
      estimatedCostUsd: zod.number(),
    }),
  ),
  note: zod.string(),
});

/**
 * @summary Diagnostic — live single request to each bookmaker source
 */
export const ProbeAdminBookmakersBody = zod.object({
  source: zod
    .string()
    .optional()
    .describe(
      "Optional — probe only this source id. Empty = all known sources.",
    ),
});

export const ProbeAdminBookmakersResponse = zod.object({
  probedAt: zod.string(),
  results: zod.array(
    zod.object({
      source: zod.string(),
      name: zod.string(),
      url: zod.string(),
      ok: zod.boolean(),
      httpStatus: zod.number().nullish(),
      contentType: zod.string().nullish(),
      bodySize: zod.number().nullish(),
      latencyMs: zod.number(),
      bodyPreview: zod.string(),
      error: zod.string().optional(),
      rateLimited: zod.boolean().optional(),
    }),
  ),
});

/**
 * @summary List external API integrations and their key status
 */
export const GetAdminIntegrationsResponse = zod.object({
  integrations: zod.array(
    zod.object({
      envName: zod.string(),
      label: zod.string(),
      description: zod.string(),
      docUrl: zod.string(),
      howToGet: zod
        .string()
        .optional()
        .describe(
          "Short Russian-language instruction on how to obtain the key\/token.",
        ),
      category: zod.enum(["data-source", "odds-feed", "network", "bookmaker"]),
      sensitive: zod.boolean(),
      configured: zod.boolean(),
      source: zod.enum(["override", "env", "none"]),
      preview: zod.string().nullish(),
      overrideUpdatedAt: zod.string().nullish(),
      requestsTotal: zod
        .number()
        .nullish()
        .describe("Total HTTP requests sent to this source since server boot."),
      responsesOk: zod
        .number()
        .nullish()
        .describe(
          "Successful responses (HTTP 2xx with parsed events) since boot.",
        ),
      lastTickStatus: zod
        .object({
          ok: zod.boolean(),
          events: zod
            .number()
            .describe(
              "Number of events returned in the last tick (0 if error).",
            ),
          error: zod.string().nullish(),
          checkedAt: zod
            .string()
            .describe("ISO timestamp of the last fetch attempt."),
          durationMs: zod.number(),
        })
        .nullish(),
    }),
  ),
});

/**
 * @summary Set or clear an integration key override (empty value clears)
 */

export const UpdateAdminIntegrationBody = zod.object({
  envName: zod.string().min(1),
  value: zod
    .string()
    .nullish()
    .describe(
      "New value; empty string or null clears the override and falls back to ENV.",
    ),
});

